typedef struct Node {
    int vertex;
    struct Node *next;
} Node;

Node* add_edge(Node *head, int v) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->vertex = v;
    n->next = head;
    return n;
}

typedef struct {
    int *data;
    int size;
} MinHeap;

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

void push_heap(MinHeap *h, int val) {
    int idx = h->size++;
    h->data[idx] = val;
    while (idx > 0) {
        int p = (idx - 1) / 2;
        if (h->data[idx] < h->data[p]) {
            swap(&h->data[idx], &h->data[p]);
            idx = p;
        } else break;
    }
}

int pop_heap(MinHeap *h) {
    int min_val = h->data[0];
    h->data[0] = h->data[--h->size];
    int idx = 0;
    while (2 * idx + 1 < h->size) {
        int smallest = idx;
        int l = 2 * idx + 1, r = 2 * idx + 2;
        if (l < h->size && h->data[l] < h->data[smallest]) smallest = l;
        if (r < h->size && h->data[r] < h->data[smallest]) smallest = r;
        if (smallest != idx) {
            swap(&h->data[idx], &h->data[smallest]);
            idx = smallest;
        } else break;
    }
    return min_val;
}

int main(void) {
    int v, e;
    if (scanf("%d %d", &v, &e) != 2) return 0;

