        adj[from] = add_edge(adj[from], to);
        in_degree[to]++;
    }

    MinHeap h;
    h.data = (int *)malloc(sizeof(int) * (v + 5));
    h.size = 0;

    for (int i = 0; i < v; i++) {
        if (in_degree[i] == 0) {
            push_heap(&h, i);
        }
    }

    int *result = (int *)malloc(sizeof(int) * v);
    int count = 0;

    while (h.size > 0) {
        int u = pop_heap(&h);
        result[count++] = u;

