} DSU;

DSU* create_dsu(int n) {
    DSU *dsu = (DSU *)malloc(sizeof(DSU));
    dsu->parent = (int *)malloc(sizeof(int) * n);
    dsu->rank = (int *)calloc(n, sizeof(int));
    dsu->count = n;
    for (int i = 0; i < n; i++) dsu->parent[i] = i;
    return dsu;
}

int find_root(DSU *dsu, int i) {
    if (dsu->parent[i] != i) {
        dsu->parent[i] = find_root(dsu, dsu->parent[i]);
    }
    return dsu->parent[i];
}

void union_sets(DSU *dsu, int u, int v) {
    int root_u = find_root(dsu, u);
    int root_v = find_root(dsu, v);
    if (root_u != root_v) {
        if (dsu->rank[root_u] < dsu->rank[root_v]) {
            dsu->parent[root_u] = root_v;
        } else if (dsu->rank[root_u] > dsu->rank[root_v]) {
            dsu->parent[root_v] = root_u;
        } else {
            dsu->parent[root_v] = root_u;
            dsu->rank[root_u]++;
        }
        dsu->count--;
    }
}

int main(void) {
    int v, q;
    if (scanf("%d %d", &v, &q) != 2) return 0;
    DSU *dsu = create_dsu(v);

    char cmd[32];
    while (q--) {
        scanf("%s", cmd);
        if (strcmp(cmd, "union") == 0) {
            int x, y;
            scanf("%d %d", &x, &y);
            union_sets(dsu, x, y);
        } else if (strcmp(cmd, "find") == 0) {
            int x;
            scanf("%d", &x);
            printf("%d\n", find_root(dsu, x));
        } else if (strcmp(cmd, "connected") == 0) {
            int x, y;
            scanf("%d %d", &x, &y);
            if (find_root(dsu, x) == find_root(dsu, y)) {
                printf("YES\n");
            } else {
                printf("NO\n");
            }
        } else if (strcmp(cmd, "count") == 0) {
            printf("%d\n", dsu->count);
        }
    }

    free(dsu->parent);
    free(dsu->rank);
    free(dsu);
    return 0;
}
